51	async function apiFetch<T>(path: string): Promise<T> {
52	  if (!TENANT_ID) {
53	    console.error("NEXT_PUBLIC_TENANT_ID not set — API calls will fail");
54	  }
55	  const res = await fetch(`${API_URL}${path}`, {
56	    cache: "no-store",
57	    headers: {
58	      "X-Tenant-ID": TENANT_ID,
59	    },
60	  });
61	  if (!res.ok) {
62	    throw new Error(`API error: ${res.status}`);
63	  }
64	  return res.json();
65	}
