91	export function estimateCost(tokens: number): string {
92	  // Canonical pricing: cli/crates/core/src/router.rs — Sonnet $3/1M tokens
93	  const costPer1k = 0.003;
94	  const cost = (tokens / 1000) * costPer1k;
95	  if (cost < 0.01) return "<$0.01";
96	  return `$${cost.toFixed(2)}`;
97	}
