105	func (c *Client) QueryProvenance(ctx context.Context, tenantID, project string, days int) ([]ProvenanceRow, error) {
106		days = clampDays(days, 90)
107		query := fmt.Sprintf(`
108			SELECT timestamp, session_id, project_dir, machine_id,
109				file_path, code_hash, model_id, model_version, contributor_type,
110				start_line, end_line, attestation_sig, developer_id, prompt_hash
111			FROM codeflow.provenance_events
112			WHERE tenant_id = $1 AND timestamp >= now() - INTERVAL %d DAY
113		`, days)
114		args := []any{tenantID}
115		if project != "" {
116			query += " AND project_dir = $2"
117			args = append(args, project)
118		}
119		query += " ORDER BY timestamp DESC LIMIT 1000"
120	
121		rows, err := c.conn.Query(ctx, query, args...)
122		if err != nil {
123			return nil, fmt.Errorf("provenance query: %w", err)
124		}
125		defer rows.Close()
126	
127		var result []ProvenanceRow
128		for rows.Next() {
129			var r ProvenanceRow
130			r.TenantID = tenantID
131			if err := rows.Scan(
132				&r.Timestamp, &r.SessionID, &r.ProjectDir, &r.MachineID,
133				&r.FilePath, &r.CodeHash, &r.ModelID, &r.ModelVersion, &r.ContributorType,
134				&r.StartLine, &r.EndLine, &r.AttestationSig, &r.DeveloperID, &r.PromptHash,
135			); err != nil {
136				slog.Warn("scan provenance row", "error", err)
137				continue
138			}
139			result = append(result, r)
140		}
141		return result, nil
142	}
